def _is_nidaan_host(request: Request) -> bool:
    """Return True when the request is for nidaanpartner.com (any env)."""
    host = request.headers.get("host", "").lower().split(":")[0]
    return host in ("nidaanpartner.com", "www.nidaanpartner.com")


