@app.get("/nidaan/branch/api/account/{account_id}")
async def nidaan_branch_account_detail(account_id: int, request: Request):
    """Branch drill-down into ONE of its referred accounts — claims + statuses + plan/payment,
    so a branch can track its referrals' progress. Strictly scoped to the token's branch;
    customer phone MASKED and internal legal notes omitted (mirrors the staff drill-down)."""
    if not _is_nidaan_host(request):
        raise HTTPException(status_code=404)
    code = _branch_bearer(request)
    if not code:
        raise HTTPException(status_code=401, detail="Unauthorized")
    import aiosqlite as _aio
    async with _aio.connect(nidaan.DB_PATH) as conn:
        conn.row_factory = _aio.Row
        cur = await conn.execute(
            """SELECT a.account_id, a.owner_name, a.phone, a.branch_code, a.created_at,
                      COALESCE(s.plan,'free') AS plan, s.status AS sub_status, s.current_period_end
               FROM nidaan_accounts a
               LEFT JOIN nidaan_subscriptions s ON s.account_id=a.account_id AND s.status='active'
               WHERE a.account_id=?""", (account_id,))
        account = dict(cur) if (cur := await cur.fetchone()) else None
        if not account:
            raise HTTPException(status_code=404, detail="Account not found")
        if (account.get("branch_code") or "").strip().upper() != (code or "").strip().upper():
            raise HTTPException(status_code=403, detail="Not your referral")
        _ph = str(account.get("phone") or "")
        account["phone_masked"] = ("•••••" + _ph[-4:]) if len(_ph) >= 4 else ""
        account.pop("phone", None)
        claims = [dict(r) for r in await (await conn.execute(
            """SELECT claim_id, claim_type, insurer_name, disputed_amount, status,
                      created_at, last_status_at
               FROM nidaan_claims WHERE account_id=? ORDER BY created_at DESC""",
            (account_id,))).fetchall()]
        reviews = [dict(r) for r in await (await conn.execute(
            """SELECT claim_type, amount_paid, status, created_at, reviewed_at
               FROM nidaan_per_claim_purchase
               WHERE account_id=? AND status NOT IN ('pending_payment','cancelled')
               ORDER BY created_at DESC""", (account_id,))).fetchall()]
    return {"account": account, "claims": claims, "reviews": reviews}


def _clean_complainant_contact(phone_in: str, email_in: str):
    """Enforce a valid 10-digit mobile + a valid email for the COMPLAINANT (the person presenting
    the case and providing documents) at every claim-creation endpoint — this is our comms point.
    Returns (phone10, email); raises HTTPException(400) with a plain-language message on failure."""
    phone = "".join(ch for ch in (phone_in or "") if ch.isdigit())
    if len(phone) >= 11 and phone.startswith("91"):
        phone = phone[-10:]
    if len(phone) != 10:
        raise HTTPException(400, "Enter a valid 10-digit mobile number for the complainant")
    email = auth.sanitize_email(email_in or "")
    if not email:
        raise HTTPException(400, "Enter a valid email for the complainant — that's where we send "
                                 "document requests and updates")
    return phone, email


def _intake_core(body, door: str) -> tuple:
    """The seven core details, checked the same at every door (biz_nidaan_intake). Returns
    (core, no_letter_reason). Raises IntakeError - including when there is neither a letter nor,
    at a door that allows it, a reason."""
    core = _intake.check_core(body.model_dump())
    reason = _intake.no_letter_reason(door, getattr(body, "no_letter_reason", ""))
    if (getattr(body, "letter_token", "") or "").strip():
        reason = ""
    elif not reason:
        raise _intake.IntakeError(
            "rejection_letter", "Attach the insurer's rejection letter - a claim cannot be raised without it.",
            "बीमा कंपनी का रिजेक्शन लेटर लगाएँ - इसके बिना क्लेम दर्ज नहीं होता।")
    return core, reason


async def _intake_letter(body, owner: str):
    """Reserve the uploaded letter for this claim - only its uploader can. None when going without."""
    token = (getattr(body, "letter_token", "") or "").strip()
    return await _intake.reserve_letter(token, owner) if token else None


async def _intake_finish(claim_id: int, letter, reason: str, *, account_id: int, claim_type: str,
                         by: str) -> None:
    """After the claim exists. Never raises: a failure here must not answer 500 for a claim that was
    made (the person would raise it again) - it falls back to the 7-day letter clock and says so."""
    try:
        if letter:
            await _intake.attach_letter(letter, claim_id=claim_id, account_id=account_id,
                                        claim_type=claim_type, by=by)
        elif reason:
            await _intake.set_letter_due(claim_id, reason, by)
    except Exception as e:  # noqa: BLE001
        logger.error("intake finish failed for claim %s: %s", claim_id, e)
        try:
            await _intake.set_letter_due(claim_id, "the uploaded letter could not be filed automatically - "
                                                   "please attach it again", "system")
        except Exception as e2:  # noqa: BLE001
            logger.error("intake fallback failed for claim %s: %s", claim_id, e2)


async def _stage_intake_letter(request: Request, owner: str, file: UploadFile) -> dict:
    """The rejection letter, before the claim exists: the same checks as every upload (size, real
    file type, virus scan), then a single-use token for the form. One file; a person staging
    letters without raising claims is capped per day."""
    _guard_upload_batch([file])
    async with __import__("aiosqlite").connect(nidaan.DB_PATH) as _c:
        try:
            n = (await (await _c.execute(
                "SELECT COUNT(*) FROM nidaan_intake_letters WHERE owner=? "
                "AND created_at > datetime('now','-1 day')", (owner,))).fetchone())[0]
        except Exception:  # noqa: BLE001 - table made on first stage
            n = 0
    if n >= 60:
        raise HTTPException(429, "Too many uploads today. Please try again tomorrow, or call us.")
    content = await file.read()
    if len(content) > _MAX_DOC_SIZE:
        raise HTTPException(413, f"{file.filename} is over the {_MAX_DOC_SIZE // (1024*1024)} MB limit")
    if not _doc_magic_ok(content):
        raise HTTPException(415, _upload_refusal(file.filename, content))
    ext = await validate_upload_scanned(content, (file.content_type or ""), what="document")
    content, ext = _as_viewable(content, ext)
    stored = f"{uuid.uuid4().hex}{ext}"
    (_NIDAAN_DOCS_DIR / stored).write_bytes(content)
    token = await _intake.stage_letter(owner, stored_name=stored,
                                       original_name=(file.filename or stored)[:200],
                                       file_size=len(content), mime_type=file.content_type or "")
    return {"token": token, "name": file.filename or stored, "size": len(content)}


